/**
 * @name Path traversal in file operations
 * @description File operations with unsanitized user input may allow path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-file-ops
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Command line arguments
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("argparse").getMember("ArgumentParser").getReturn().getMember("parse_args").getACall() |
      source = call.getAMethodCall("__getattribute__")
    )
    or
    exists(DataFlow::AttrRead attr |
      attr.getAttributeName() in ["input", "output"] and
      source = attr
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user input"

/**
 * @name Potential XSS via HTML rendering
 * @description User-controlled content that flows to HTML output without proper escaping
 * @kind path-problem
 * @problem.severity error
 * @id py/xss-html-rendering
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module XSSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameter nodes from render methods
    exists(DataFlow::ParameterNode p |
      p = source and
      (
        p.getParameter().getName() = "content" or
        p.getParameter().getName() = "text" or
        p.getParameter().getName() = "src" or
        p.getParameter().getName() = "tokens"
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // String concatenation or formatting that builds HTML
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(_) and
      (
        call.getFunction().(DataFlow::AttrRead).getAttributeName() = "format" or
        call.getFunction().(DataFlow::AttrRead).getAttributeName() = "join"
      )
    )
  }
}

module XSSFlow = TaintTracking::Global<XSSConfig>;
import XSSFlow::PathGraph

from XSSFlow::PathNode source, XSSFlow::PathNode sink
where XSSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XSS: user content flows to HTML output from $@.", source.getNode(), "here"
